// Generated by scripts/build-figma-button.js: don't edit, rebuild.
// Figma plugin script for the Figma MCP use_figma tool. It updates the Button component set on the
// Button page in place (variants by name; missing ones created, none deleted) and rebuilds the page
// around it (decision 58): the purpose, the set, and "All components", every variant and state. Needs the color, typography, spacing, radius, focus, border-width and opacity
// collections and the label text style. Safe to run again: variant IDs stay the same.
const PLAN = {
  "variants": [
    {
      "variant": "Primary",
      "size": "Main",
      "label": "View my work",
      "minHeight": "space/12",
      "paddingX": "space/8",
      "fill": "color/action",
      "fillHover": "color/action-hover",
      "text": "color/text-on-action"
    },
    {
      "variant": "Secondary",
      "size": "Main",
      "label": "Download CV",
      "minHeight": "space/12",
      "paddingX": "space/8",
      "fill": "color/secondary",
      "fillHover": "color/secondary-hover",
      "text": "color/text-on-secondary",
      "stroke": "color/border-highlight"
    },
    {
      "variant": "Link",
      "size": "Main",
      "label": "Case studies",
      "minHeight": "space/6",
      "text": "color/text-muted",
      "textHover": "color/text",
      "noDisable": true,
      "square": true
    },
    {
      "variant": "Primary",
      "size": "Navigation",
      "label": "Let's talk",
      "minHeight": "space/8",
      "paddingX": "space/6",
      "fill": "color/action",
      "fillHover": "color/action-hover",
      "text": "color/text-on-action"
    }
  ],
  "states": [
    "Default",
    "Hover",
    "Focus",
    "Active",
    "Disabled",
    "Loading"
  ],
  "shared": {
    "gap": "space/2",
    "radius": "radius/pill",
    "strokeWeight": "border-width/control",
    "opacity": "opacity/disabled",
    "focusColor": "color/focus",
    "focusWidth": "focus/ring-width",
    "focusOffset": "focus/ring-offset",
    "textStyle": "label",
    "loadingLabel": "Sending…"
  },
  "componentPage": "Button",
  "legacyPage": "Button check",
  "purpose": "A control that takes the visitor somewhere or does something.",
  "allSubtitle": "Every variant in every state, on a light and a dark surface."
};

const vars = await figma.variables.getLocalVariablesAsync();
const v = (name) => {
  const found = vars.find((x) => x.name === name);
  if (!found) throw new Error('Variable not found: ' + name);
  return found;
};
const paint = (name) => figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', v(name));
const labelStyle = (await figma.getLocalTextStylesAsync()).find((s) => s.name === PLAN.shared.textStyle);
if (!labelStyle) throw new Error('No "' + PLAN.shared.textStyle + '" text style: run typography-collection.js first.');
await figma.loadFontAsync(labelStyle.fontName);
await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });


// ── Documentation page layout (decision 58), shared by every page script ──
const DOC_ORDER = ["Colors","Typography","Spacing","Corner radius","Shadows","Button"];
const docVars = await figma.variables.getLocalVariablesAsync();
const docVar = (name) => {
  const found = docVars.find((x) => x.name === name);
  if (!found) throw new Error('Variable not found: ' + name);
  return found;
};
const docPaint = (name) => figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', docVar(name));
const docStyles = await figma.getLocalTextStylesAsync();
const docStyle = (name) => {
  const found = docStyles.find((s) => s.name === name);
  if (!found) throw new Error('Text style not found: ' + name + ' (run typography-collection.js first)');
  return found;
};
for (const s of docStyles) await figma.loadFontAsync(s.fontName);
const docCollections = await figma.variables.getLocalVariableCollectionsAsync();
const docModeOf = (collection, mode) => {
  const c = docCollections.find((x) => x.name === collection);
  return [c, c.modes.find((m) => m.name === mode).modeId];
};

// Puts the documentation pages first, in the documented order, and removes the empty "Page 1"
// that every new Figma file starts with.
function docOrder() {
  let i = 0;
  for (const name of DOC_ORDER) {
    const p = figma.root.children.find((x) => x.name === name);
    if (!p) continue;
    if (figma.root.children.indexOf(p) !== i) figma.root.insertChild(i, p);
    i++;
  }
  const blank = figma.root.children.find((x) => x.name === 'Page 1' && x.children.length === 0);
  if (blank && blank !== figma.currentPage && figma.root.children.length > 1) blank.remove();
}

async function docPage(name) {
  let page = figma.root.children.find((x) => x.name === name);
  if (!page) { page = figma.createPage(); page.name = name; }
  await figma.setCurrentPageAsync(page);
  docOrder();
  return page;
}

// Light or dark surface, desktop type sizes.
function docSurface(frame, mode) {
  const [cc, cid] = docModeOf('color', mode);
  frame.setExplicitVariableModeForCollection(cc, cid);
  const [tc, tid] = docModeOf('typography', 'Desktop');
  frame.setExplicitVariableModeForCollection(tc, tid);
  frame.fills = [docPaint(mode === 'Dark surface' ? 'color/surface-dark' : 'color/background')];
}

function docFrame(name, direction, props) {
  const f = figma.createAutoLayout(direction, Object.assign({ name }, props || {}));
  f.fills = [];
  return f;
}

async function docText(chars, style, color, width) {
  const t = figma.createText();
  await t.setTextStyleIdAsync(docStyle(style).id);
  t.characters = String(chars);
  t.fills = [docPaint(color)];
  if (width) { t.resize(width, t.height); t.textAutoResize = 'HEIGHT'; }
  return t;
}

// The page frame: everything on a page sits in it, on the light surface.
function docRoot(page, width) {
  const root = docFrame(page.name, 'VERTICAL', { itemSpacing: 96, paddingTop: 80, paddingBottom: 80, paddingLeft: 80, paddingRight: 80 });
  page.appendChild(root);
  root.counterAxisSizingMode = 'FIXED';
  root.resize(width, root.height);
  docSurface(root, 'Light surface');
  return root;
}

// A section: a title (heading, or subheading for a smaller section) and a one-sentence subtitle,
// then its content. Returns the section frame; append the content to it.
async function docSection(parent, title, subtitle, level) {
  const section = docFrame(title, 'VERTICAL', { itemSpacing: 32 });
  parent.appendChild(section);
  const head = docFrame('title', 'VERTICAL', { itemSpacing: 12 });
  section.appendChild(head);
  head.appendChild(await docText(title, level || 'heading', 'color/text'));
  head.appendChild(await docText(subtitle, 'lead', 'color/text-muted', 880));
  return section;
}


// ── The component set: updated in place ──
// Existing variants are found by name and updated, missing ones are created, none are deleted, so
// their IDs (and every instance in a design) stay the same from run to run.
const componentPage = await docPage(PLAN.componentPage);
let set = componentPage.findOne((n) => n.type === 'COMPONENT_SET' && n.name === 'Button');

const RADII = ['topLeftRadius', 'topRightRadius', 'bottomLeftRadius', 'bottomRightRadius'];
const PADDING = ['paddingLeft', 'paddingRight', 'paddingTop', 'paddingBottom'];
const bindRadius = (node, on) => RADII.forEach((f) => { node.setBoundVariable(f, on ? v(PLAN.shared.radius) : null); if (!on) node[f] = 0; });
const unbind = (node, fields) => fields.forEach((f) => { node.setBoundVariable(f, null); node[f] = 0; });

// Sets every property of one variant, whatever it was before.
async function fill(comp, row, state) {
  const hover = state === 'Hover' || state === 'Active';
  comp.layoutMode = 'HORIZONTAL';
  comp.primaryAxisSizingMode = 'AUTO'; comp.counterAxisSizingMode = 'AUTO';
  comp.fills = [];
  bindRadius(comp, !row.square);
  if (state === 'Focus') {
    for (const f of PADDING) comp.setBoundVariable(f, v(PLAN.shared.focusOffset));
    comp.strokes = [paint(PLAN.shared.focusColor)];
    comp.strokeAlign = 'OUTSIDE';
    comp.setBoundVariable('strokeWeight', v(PLAN.shared.focusWidth));
  } else {
    unbind(comp, PADDING);
    comp.strokes = [];
    comp.setBoundVariable('strokeWeight', null);
  }
  if (state === 'Disabled') comp.setBoundVariable('opacity', v(PLAN.shared.opacity));
  else { comp.setBoundVariable('opacity', null); comp.opacity = 1; }

  let btn = comp.findChild((n) => n.name === 'button');
  if (!btn) { btn = figma.createFrame(); btn.name = 'button'; comp.appendChild(btn); }
  btn.layoutMode = 'HORIZONTAL';
  btn.primaryAxisSizingMode = 'AUTO'; btn.counterAxisSizingMode = 'AUTO';
  btn.primaryAxisAlignItems = 'CENTER'; btn.counterAxisAlignItems = 'CENTER';
  btn.setBoundVariable('itemSpacing', v(PLAN.shared.gap));
  btn.setBoundVariable('minHeight', v(row.minHeight));
  if (row.paddingX) { btn.setBoundVariable('paddingLeft', v(row.paddingX)); btn.setBoundVariable('paddingRight', v(row.paddingX)); }
  else unbind(btn, ['paddingLeft', 'paddingRight']);
  btn.fills = row.fill ? [paint(hover && row.fillHover ? row.fillHover : row.fill)] : [];
  bindRadius(btn, !!row.fill);
  if (row.stroke) {
    btn.strokes = [paint(row.stroke)];
    btn.strokeAlign = 'INSIDE';
    btn.setBoundVariable('strokeWeight', v(PLAN.shared.strokeWeight));
  } else { btn.strokes = []; btn.setBoundVariable('strokeWeight', null); }

  let text = btn.findChild((n) => n.type === 'TEXT');
  if (!text) { text = figma.createText(); btn.appendChild(text); }
  await text.setTextStyleIdAsync(labelStyle.id);
  text.characters = state === 'Loading' ? PLAN.shared.loadingLabel : row.label;
  text.fills = [paint(hover && row.textHover ? row.textHover : row.text)];
}

const ids = { updated: [], created: [] };
const fresh = [];
for (const row of PLAN.variants) {
  for (const state of PLAN.states) {
    if (row.noDisable && (state === 'Disabled' || state === 'Loading')) continue;
    const name = 'Variant=' + row.variant + ', Size=' + row.size + ', State=' + state;
    let comp = set ? set.findChild((n) => n.name === name) : null;
    if (comp) ids.updated.push(comp.id);
    else { comp = figma.createComponent(); comp.name = name; fresh.push(comp); }
    await fill(comp, row, state);
  }
}
if (!set) {
  set = figma.combineAsVariants(fresh, componentPage);
  set.name = 'Button';
} else {
  for (const comp of fresh) set.appendChild(comp);
}
ids.created = fresh.map((c) => c.id);
set.description = 'Primary, secondary and link, with a navigation size. Bound to the color, spacing, radius, focus, border-width and opacity variables and the label text style; a frame in "Dark surface" mode switches it. Same as components/button.css.';
// Lay the variants out in a grid: one row per variant row, one column per state.
set.layoutMode = 'NONE';
const COL = 260, ROWH = 90;
for (const comp of set.children) {
  const props = Object.fromEntries(comp.name.split(', ').map((p) => p.split('=')));
  const r = PLAN.variants.findIndex((x) => x.variant === props.Variant && x.size === props.Size);
  const c = PLAN.states.indexOf(props.State);
  if (r < 0 || c < 0) continue; // a variant the plan doesn't know stays where it is
  comp.x = 24 + c * COL; comp.y = 24 + r * ROWH;
}
set.resize(24 * 2 + PLAN.states.length * COL, 24 * 2 + PLAN.variants.length * ROWH);

// The set sits in a frame that sets the light surface and desktop modes: main components show their
// bound colours only inside a frame with modes. The modes are on the frame, not on the components,
// so instances still take their surface from where they're placed. The frame is kept between runs.
let holder = set.parent.type === 'FRAME' && set.parent.name === 'Component set' ? set.parent : null;
if (!holder) {
  holder = figma.createFrame();
  holder.name = 'Component set';
  componentPage.appendChild(holder);
  holder.appendChild(set);
}
set.x = 0; set.y = 0;
holder.resize(set.width, set.height);
docSurface(holder, 'Light surface');

// ── The page around the set: rebuilt on every run ──
const legacy = figma.root.children.find((p) => p.name === PLAN.legacyPage);
if (legacy) legacy.remove();
for (const child of [...componentPage.children]) if (child !== holder) child.remove();

const root = docRoot(componentPage, 80 + set.width + 80 + 1520 + 80);
await docSection(root, 'Button', PLAN.purpose);
const body = docFrame('body', 'HORIZONTAL', { itemSpacing: 80 });
root.appendChild(body);
// A placeholder that keeps the component set's place in the layout; the set sits on top of it.
const slot = figma.createFrame();
slot.name = 'Component set placeholder'; slot.fills = [];
slot.resize(set.width, set.height);
body.appendChild(slot);

const all = await docSection(body, 'All components', PLAN.allSubtitle, 'subheading');
const frames = [];
for (const mode of ['Light surface', 'Dark surface']) {
  const frame = docFrame(mode, 'VERTICAL', { itemSpacing: 16, paddingTop: 40, paddingBottom: 40, paddingLeft: 40, paddingRight: 40 });
  all.appendChild(frame);
  docSurface(frame, mode);

  const header = docFrame('states', 'HORIZONTAL', { itemSpacing: 0 });
  frame.appendChild(header);
  header.appendChild(await docText(mode, 'overline', 'color/text-muted', 120));
  for (const s of PLAN.states) header.appendChild(await docText(s, 'small', 'color/text-muted', 220));

  for (const row of PLAN.variants) {
    const line = docFrame(row.variant + ' · ' + row.size, 'HORIZONTAL', { itemSpacing: 0, counterAxisAlignItems: 'CENTER' });
    frame.appendChild(line);
    line.appendChild(await docText(row.size === 'Main' ? row.variant : row.size, 'small', 'color/text-muted', 120));
    for (const s of PLAN.states) {
      const cell = docFrame(s, 'HORIZONTAL', { counterAxisAlignItems: 'CENTER' });
      line.appendChild(cell);
      cell.primaryAxisSizingMode = 'FIXED'; cell.counterAxisSizingMode = 'FIXED'; cell.resize(220, 72);
      const comp = set.children.find((c) => c.name === 'Variant=' + row.variant + ', Size=' + row.size + ', State=' + s);
      cell.appendChild(comp ? comp.createInstance() : await docText('n/a', 'small', 'color/text-muted', 120));
    }
  }
  frames.push({ id: frame.id, name: frame.name, width: Math.round(frame.width), height: Math.round(frame.height) });
}

// The set's frame on top of its placeholder (moving it keeps every ID).
componentPage.appendChild(holder);
holder.x = slot.absoluteBoundingBox.x;
holder.y = slot.absoluteBoundingBox.y;

return { componentSetId: set.id, variants: set.children.length, updated: ids.updated.length, created: ids.created.length,
  variantIds: set.children.map((c) => c.id).sort(), page: componentPage.id, frames };
